import sys; sys.path.insert(0,'/home/claude/ac-mdcu/parts')
from l23_common import mk, save
Q={}

mk(Q, 61, [26, 's10', 's12'],
 stem='A 28-year-old man rescued from a house fire is drowsy and has a COHb of 35%. Arterial blood gas on room air shows a PaO2 of 95 mm Hg. Which statement is correct?',
 opts=['PaO2 is always low in carbon monoxide poisoning','A COHb of 35% is a typical finding in heavy smokers','Oxygen therapy is unnecessary because the measured PaO2 is normal','A normal PaO2 does not exclude severe carbon monoxide poisoning','The normal PaO2 proves that oxygen delivery is adequate'],
 interp='ผู้ป่วยไฟไหม้บ้าน ง่วงซึม COHb 35% แต่ PaO2 95 mm Hg ขณะหายใจอากาศปกติ → พิษ CO ระดับปานกลางถึงรุนแรง → ถามว่าตัวเลข PaO2 ที่ปกติแปลว่าอะไร ต้องใช้หลักว่า PaO2 วัด O2 ที่ละลายในพลาสมา ไม่ได้บอกว่า Hb จับ O2 ได้จริงเท่าไร',
 why='<b>PaO2</b> คือแรงดันของ O2 ที่<b>ละลายในพลาสมา</b> ขึ้นกับ FiO2 และการทำงานของถุงลม — CO ไม่ได้ขัดขวางการแลกเปลี่ยนก๊าซที่ถุงลม PaO2 จึง<b>มักปกติ</b> · ปัญหาอยู่ที่ CO จับ Hb แน่นกว่า O2 ราว <b>210 เท่า</b> ทำให้ Hb 35% ใช้ขน O2 ไม่ได้ และ Hb ที่เหลือปล่อย O2 ยากขึ้นเพราะกราฟ oxyhemoglobin <b>เลื่อนซ้าย</b> → <b>O2 content</b> (≈ 1.34 × Hb × SaO2 + 0.003 × PaO2) ลดลงมาก แม้ PaO2 95 mm Hg · นอกจากนี้ CO ยังเข้าไปกด <b>cytochrome oxidase</b> ใน mitochondria เซลล์จึงใช้ O2 ไม่ได้ เกิด lactic acidosis · ค่าที่ต้องดูคือ <b>COHb และ SaO2 ที่วัดจริงด้วย co-oximetry</b> — SaO2 ที่เครื่อง blood gas ทั่วไปคำนวณจาก PaO2 จะออกมาปกติลวง เช่นเดียวกับ SpO2 ที่อ่าน COHb เป็น oxyhemoglobin · ผู้ป่วยต้องได้ O2 100% ทันทีไม่ว่า PaO2 เท่าไร · สไลด์หน้า 26 <b>"Affinity for Hgb is 210 times O2"</b> และ <b>"Impair oxygen utilization"</b>',
 wrong={
 'A':'PaO2 ต่ำเป็นลักษณะของปอดที่แลกเปลี่ยนก๊าซไม่ได้ ไม่ใช่ของพิษ CO ซึ่งแย่งที่บน Hb โดยไม่ลด O2 ที่ละลายในพลาสมา คำว่า always จึงผิด · ไม่มีสถานการณ์ใดที่พิษ CO ทำให้ PaO2 ต่ำได้ทุกราย เพราะ PaO2 ขึ้นกับ FiO2 และปอด หาก PaO2 ต่ำในผู้ป่วยไฟไหม้ต้องหาสาเหตุร่วม เช่น inhalation injury ARDS หรือหายใจแผ่ว',
 'B':'ผู้สูบบุหรี่จัดมี COHb พื้นฐานสูงกว่าคนทั่วไปได้ แต่ตารางระดับ COHb ให้ช่วงที่พบในผู้สูบจัดเพียง 0–10% และแทบไม่มีอาการ ส่วน 35% คือพิษที่ทำให้สับสนกระสับกระส่าย · ไม่มีสถานการณ์ใดที่การสูบบุหรี่อย่างเดียวทำให้ COHb สูงถึง 35% เพราะระดับนี้ต้องมาจากการสูดควันหรือก๊าซที่มี CO เข้มข้น เช่น ไฟไหม้ในที่ปิดหรือเครื่องยนต์ในห้องปิด',
 'C':'การให้ O2 ในพิษ CO ไม่ได้มีไว้แก้ PaO2 ต่ำ แต่ใช้ O2 ความเข้มข้นสูงไล่ CO ออกจาก Hb และลด half-life จากราว 4 ชั่วโมงลงเหลือไม่ถึงชั่วโมงครึ่ง · ไม่มีสถานการณ์ใดที่ PaO2 ปกติทำให้ผู้ป่วยพิษ CO ไม่ต้องได้ O2 เพราะ PaO2 ไม่สะท้อน COHb และการรักษาหลักของพิษ CO ที่มีอาการทุกระดับคือ O2 100%',
 'E':'O2 delivery เท่ากับ cardiac output คูณ O2 content ซึ่งขึ้นกับ Hb ที่จับ O2 ได้จริงเป็นหลัก ส่วน PaO2 มีสัดส่วนน้อยมาก และในพิษ CO เซลล์ยังใช้ O2 ไม่ได้เพราะ cytochrome ถูกกด · ไม่มีสถานการณ์ใดที่ PaO2 ปกติพิสูจน์ได้ว่า O2 ถึงเนื้อเยื่อพอในพิษ CO เพราะต้องดู COHb, SaO2 จาก co-oximetry, lactate และอาการทางสมองกับหัวใจร่วมกัน'},
 trap='คุ้นกับการใช้ PaO2 วัดภาวะขาด O2 จึงคิดว่า PaO2 ปกติแปลว่าไม่ขาด O2 และลายมือบนสไลด์ยังเขียนว่าเจาะ blood gas จะเห็น PaO2 ต่ำ ทำให้เลือกช้อย A · วิธีแยก: ถามตัวเองว่าค่านั้นวัด O2 ที่ละลายในพลาสมา (PaO2) หรือวัด Hb ที่จับ O2 จริง (SaO2 จาก co-oximetry) — พิษ CO กระทบตัวหลัง',
 summary=['PaO2 ปกติไม่ตัดพิษ CO รุนแรง — CO ลด O2 content ผ่าน Hb ไม่ได้ลด O2 ที่ละลายในพลาสมา',
  'O2 content ≈ 1.34 × Hb × SaO2 + 0.003 × PaO2 → ส่วนที่ Hb ขนมีน้ำหนักมากกว่าส่วนที่ละลายหลายสิบเท่า',
  'CO จับ Hb แน่นกว่า O2 ราว 210 เท่า + กราฟ oxyhemoglobin เลื่อนซ้าย → ปล่อย O2 ให้เนื้อเยื่อยาก',
  'CO กด cytochrome oxidase → เซลล์ใช้ O2 ไม่ได้ → lactic acidosis แม้ PaO2 ปกติ',
  'SpO2 และ SaO2 ที่คำนวณจาก PaO2 ปกติลวงทั้งคู่ — ต้องวัด COHb ด้วย co-oximetry ซึ่งใช้เลือดแดงหรือเลือดดำก็ได้',
  'COHb 35% อยู่ในช่วงสับสนกระสับกระส่าย (30–40%) → O2 100% ทันที และพิจารณา hyperbaric oxygen เมื่อมีอาการทางสมอง'],
 opinion='เห็นด้วยกับคำตอบ D ความมั่นใจสูง — เป็นหลักสรีรวิทยาพื้นฐานและตรงกับ ACEP Clinical Policy 2017 ที่ไม่ให้ใช้ SpO2 หรือ PaO2 คัดกรองพิษ CO · จุดที่ต้องระวัง: ลายมือสไลด์หน้า 26 เขียนว่า <b>"เจาะ blood gas = PaO2 ↓"</b> ซึ่งไม่ถูก PaO2 มักปกติ ค่าที่ต่ำคือ SaO2 ที่วัดจริงและ O2 content · ชีทหน้า 12 เขียนว่าการตรวจที่ได้ผลต้องเป็น arterial blood gas เท่านั้น — ที่ถูกคือต้องเป็นเครื่องที่มี <b>co-oximetry</b> และตัวอย่างเลือดดำก็ใช้วัด COHb ได้ใกล้เคียงเลือดแดง',
 mnemonic='<b>“PaO2 ปกติ ≠ O2 ถึงเซลล์ — CO ขโมย Hb ไม่ได้ขโมยพลาสมา”</b>',
 guide='ACEP Clinical Policy: Critical Issues in the Evaluation and Management of Adult Patients Presenting to the Emergency Department with Acute Carbon Monoxide Poisoning (Ann Emerg Med 2017;69:98–107); Sabiston Textbook of Surgery 21st ed. (2022) — Burns',
 variants=['ชายติดอยู่ในโกดังที่ไฟไหม้ PaO2 ปกติ COHb 12% แต่ lactate 11 mmol/L และความดันต่ำ → สงสัยพิษ cyanide จากการเผาไหม้พลาสติก ให้ hydroxocobalamin ร่วมกับ O2 100%',
  'หญิงพิษ CO มี PaO2 55 mm Hg ทั้งที่ได้ O2 และภาพปอดมีฝ้ากระจายสองข้าง → PaO2 ต่ำมาจาก inhalation injury หรือ ARDS ร่วม ไม่ได้มาจาก CO ต้องประเมินทางเดินหายใจและปอดเพิ่ม',
  'เครื่อง blood gas ที่ไม่มี co-oximetry รายงาน SaO2 98% ในชายพิษ CO → เป็นค่าคำนวณจาก PaO2 เชื่อไม่ได้ ต้องส่งวัด COHb ด้วย co-oximetry',
  'เจ้าหน้าที่ดับเพลิงปวดศีรษะ มีเพียงตัวอย่างเลือดดำ → วัด COHb จากเลือดดำด้วย co-oximetry ได้ ไม่จำเป็นต้องเจาะเลือดแดงเพื่อวินิจฉัย'])

mk(Q, 62, [27, 's10'],
 stem='A woman rescued from a house fire is confused and agitated. Which carboxyhemoglobin range best fits these symptoms?',
 opts=['30–40%','40–50%','0–10%','Above 50%','10–20%'],
 interp='ผู้ป่วยไฟไหม้บ้านมาด้วยสับสนและกระสับกระส่าย ยังไม่หมดสติ → สงสัยพิษ CO ที่เริ่มกระทบการทำงานของสมอง → ถามว่าระดับ COHb ช่วงไหนเข้ากับอาการนี้ ต้องใช้ตารางระดับ COHb เทียบอาการที่ไล่จากน้อยไปมาก',
 why='ตาราง <b>COHb levels versus symptoms</b> ไล่ความรุนแรงตามสัดส่วน Hb ที่ถูก CO จับ: <b>0–10%</b> แทบไม่มีอาการ (พบในผู้สูบจัด) → <b>10–20%</b> คลื่นไส้ ปวดศีรษะ → <b>20–30%</b> ง่วงซึม อ่อนแรง → <b>30–40% สับสน กระสับกระส่าย</b> → <b>40–50%</b> โคม่า หายใจกดลง → <b>เกิน 50%</b> เสียชีวิต · อวัยวะที่ใช้ O2 มากที่สุดคือ<b>สมองและหัวใจ</b> จึงแสดงอาการก่อน เมื่อ O2 content ลดลงราวหนึ่งในสาม สมองเริ่มทำงานผิดปกติ ตั้งแต่สับสนไปจนหมดสติ · ในทางปฏิบัติ ระดับที่วัดได้<b>สัมพันธ์กับอาการไม่แน่นอน</b> เพราะ COHb ลดลงตามเวลาและเมื่อได้ O2 ระหว่างทาง และผู้ป่วยไฟไหม้อาจสับสนจากสาเหตุอื่นร่วม เช่น ขาด O2 จากทางเดินหายใจ พิษ cyanide หรือบาดเจ็บศีรษะ — ตารางจึงใช้เป็นแผนที่เชื่อมระดับกับอาการ ส่วนการรักษาให้ O2 100% ทันทีโดยไม่รอผล · สไลด์หน้า 27 ตาราง <b>"30–40%: Confusion, agitation"</b>',
 wrong={
 'B':'40–50% คือระดับที่สมองขาด O2 จนหมดสติและศูนย์หายใจถูกกด ซึ่งหนักกว่าผู้ป่วยที่ยังรู้สึกตัวแต่สับสน · จะถูกถ้าชายที่ถูกพาออกจากห้องนอนที่ไฟไหม้ไม่รู้สึกตัว ปลุกไม่ตื่น หายใจช้าและตื้น ซึ่งตารางจัดไว้ที่ coma, respiratory depression',
 'C':'0–10% เป็นช่วงที่แทบไม่มีอาการ และพบได้ในผู้สูบบุหรี่จัดโดยไม่ต้องสัมผัสควันไฟเลย ระดับนี้ไม่พอทำให้สับสน · จะถูกถ้าหญิงสูบบุหรี่วันละซองที่ช่วยขนของออกจากบ้านที่ไฟไหม้เพียงชั่วครู่ ไม่มีอาการใดเลย และตรวจระบบประสาทปกติ',
 'D':'เกิน 50% คือระดับที่ตารางระบุว่าเสียชีวิต Hb กว่าครึ่งใช้ขน O2 ไม่ได้ร่วมกับกราฟเลื่อนซ้าย หัวใจและสมองหยุดทำงาน · จะถูกถ้าผู้ประสบเหตุที่พบเสียชีวิตในห้องปิดที่ไฟไหม้ ไม่มีบาดแผลรุนแรงอื่น และตรวจเลือดหลังเสียชีวิตเพื่อหาสาเหตุการตาย',
 'E':'10–20% ทำให้มีอาการไม่จำเพาะ คือปวดศีรษะ คลื่นไส้ ซึ่งมักถูกมองข้ามว่าเป็นไข้หวัดหรืออาหารเป็นพิษ แต่ยังไม่ถึงขั้นสับสน · จะถูกถ้าครอบครัวที่จุดเตาถ่านในห้องปิดตลอดคืน ตื่นมาปวดศีรษะ คลื่นไส้ทั้งบ้าน แต่ทุกคนรู้ตัวดีและพูดคุยรู้เรื่อง'},
 trap='ช่วง 20–30% (ง่วงซึม อ่อนแรง) กับ 30–40% (สับสน กระสับกระส่าย) อยู่ติดกันและฟังคล้ายกัน ส่วน 40–50% ก็มีอาการทางสมองเหมือนกัน · วิธีแยก: ดูระดับความรู้สึกตัว — ง่วงแต่ปลุกตื่นและคิดได้ = 20–30% · ตื่นแต่สับสนวุ่นวาย = 30–40% · ปลุกไม่ตื่น = 40–50%',
 summary=['สับสน กระสับกระส่าย = COHb 30–40% ตามตาราง COHb levels versus symptoms',
  'ลำดับอาการ: 0–10% แทบไม่มี → 10–20% ปวดศีรษะ คลื่นไส้ → 20–30% ง่วง อ่อนแรง → 30–40% สับสน → 40–50% โคม่า หายใจกด → &gt;50% ตาย',
  'สมองและหัวใจใช้ O2 มากที่สุดจึงแสดงอาการก่อน — อาจมีเจ็บหน้าอก หัวใจเต้นผิดจังหวะ หรือ troponin สูงร่วม',
  'ระดับที่วัดได้สัมพันธ์กับอาการไม่แน่นอน เพราะลดลงตามเวลาและเมื่อได้ O2 ก่อนถึงโรงพยาบาล',
  'สับสนในผู้ป่วยไฟไหม้ต้องคิดถึงสาเหตุร่วมเสมอ: hypoxia จากทางเดินหายใจ · พิษ cyanide · บาดเจ็บศีรษะ · ช็อก',
  'มีอาการทางสมอง = พิษ CO รุนแรง → O2 100% ทันที และพิจารณา hyperbaric oxygen'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงตามตารางสไลด์หน้า 27 และชีทหน้า 10 คำต่อคำ · ข้อควรรู้เพิ่ม: แนวทางปัจจุบัน (ACEP Clinical Policy 2017, UHMS 2019) ระบุว่าระดับ COHb ทำนายความรุนแรงและผลระยะยาวได้ไม่ดี การตัดสินใจรักษาจึงอิงอาการเป็นหลัก — ผู้ป่วยที่สับสน หมดสติ หรือมีความผิดปกติทางระบบประสาท ถือเป็นพิษรุนแรงไม่ว่าระดับ COHb เท่าไร และเป็นเหตุให้พิจารณา hyperbaric oxygen เพื่อลด delayed neurologic sequelae · ตารางยังใช้ได้ดีในฐานะแผนที่อาการตามระดับ',
 mnemonic='<b>“ขึ้นทีละสิบ: ปวดหัว → ง่วง → งง → โคม่า → ตาย (เริ่มที่ 10)”</b>',
 guide='UHMS Hyperbaric Oxygen Therapy Indications 14th ed. (2019) — Carbon monoxide poisoning; ACEP Clinical Policy: Acute Carbon Monoxide Poisoning (Ann Emerg Med 2017;69:98–107)',
 variants=['ชายหายจากพิษ CO กลับบ้านได้ 3 สัปดาห์ต่อมาความจำแย่ลง บุคลิกเปลี่ยน เดินช้า → delayed neurologic sequelae ของพิษ CO',
  'หญิงอายุ 60 ปีพิษ CO มีเจ็บแน่นหน้าอก ECG มี ST depression → myocardial injury จาก CO ตรวจ troponin และติดตามคลื่นหัวใจ',
  'ชายถูกพาออกจากไฟไหม้ สับสนอยู่ แต่ COHb วัดได้ 8% หลังได้ O2 บนรถพยาบาล 2 ชั่วโมง → ระดับลดไปแล้ว ยังถือเป็นพิษรุนแรงตามอาการ'])

mk(Q, 63, [27, 's10', 's12'],
 stem='A 25-year-old man who smokes two packs a day briefly helped neighbors at a house fire. He has no symptoms, and his COHb is 8%. How should this level be interpreted?',
 opts=['It can be found in heavy smokers and usually causes minimal symptoms','It is high enough to explain coma','It is a level usually incompatible with life','It indicates severe poisoning needing immediate intubation and ventilation','It confirms cyanide poisoning from the smoke'],
 interp='ชายสูบบุหรี่จัดวันละสองซอง ช่วยดับไฟเพียงชั่วครู่ ไม่มีอาการ COHb 8% → ถามว่าตัวเลขนี้มีความหมายอย่างไร ต้องรู้ค่า COHb พื้นฐานของผู้สูบบุหรี่ และรู้ว่าต้องแปลระดับร่วมกับประวัติและอาการเสมอ',
 why='ร่างกายสร้าง CO เองเล็กน้อยจากการสลาย heme คนไม่สูบบุหรี่จึงมี <b>COHb พื้นฐานราว 1–3%</b> · ควันบุหรี่มี CO สูง ผู้สูบบุหรี่มี COHb <b>ราว 5–10%</b> ผู้สูบจัดอาจสูงกว่านี้เล็กน้อย โดยร่างกายปรับตัวได้และ<b>แทบไม่มีอาการ</b> · ตารางจัด 0–10% เป็นช่วง <b>minimal symptoms</b> ที่พบบ่อยในผู้สูบจัด ระดับ 8% ในชายที่ไม่มีอาการจึง<b>อธิบายได้ด้วยบุหรี่เอง</b> และไม่ใช่หลักฐานของพิษ CO จากไฟ · หลักการแปล COHb: ต้องดู <b>ประวัติสูบบุหรี่ เวลาตั้งแต่สัมผัส และการได้ O2 ก่อนเจาะ</b> เพราะค่าเท่ากันอาจมีความหมายต่างกัน — 8% ในคนไม่สูบบุหรี่บ่งว่าสัมผัส CO จริง และค่าที่ต่ำหลังได้ O2 มานานไม่ได้ตัดพิษรุนแรงที่เกิดก่อนหน้า · ผู้ที่ไม่มีอาการไม่ต้องใส่ท่อ ประเมินซ้ำและให้ O2 ระหว่างสังเกตอาการได้ · สไลด์หน้า 27 <b>"0–10%: Minimal symptoms (frequently found in heavy smokers)"</b>',
 wrong={
 'B':'COHb ที่ทำให้หมดสติอยู่ราว 40–50% สูงกว่า 8% หลายเท่า และชายในโจทย์ก็รู้สึกตัวดี ไม่มีอาการ · จะถูกถ้าหญิงที่ถูกพาออกจากห้องที่ไฟไหม้ไม่รู้สึกตัว ไม่มีบาดเจ็บศีรษะ และวัด COHb ได้ 45% ก่อนได้ O2 ซึ่งระดับนี้สูงพอจะอธิบายการหมดสติได้',
 'C':'ระดับที่ตารางระบุว่าเสียชีวิตคือเกิน 50% ส่วน 8% เป็นช่วงที่พบในคนสูบบุหรี่ที่ใช้ชีวิตตามปกติ · จะถูกถ้าชายที่พบเสียชีวิตในรถที่ติดเครื่องไว้ในโรงรถปิด ตรวจศพพบ COHb 65% ซึ่งเป็นระดับที่โดยทั่วไปเข้ากันไม่ได้กับการมีชีวิต',
 'D':'พิษ CO รุนแรงที่ต้องใส่ท่อช่วยหายใจคือรายที่หมดสติหรือหายใจกดลง ซึ่งตารางจัดไว้ที่ 40–50% ขึ้นไป หรือมีปัญหาทางเดินหายใจร่วม · จะถูกถ้าชายจากห้องนอนที่ไฟไหม้ GCS 6 หายใจช้าตื้น COHb 48% ซึ่งตีความได้ว่าเป็นพิษรุนแรงที่ต้องใส่ท่อและช่วยหายใจทันที',
 'E':'COHb วัดเฉพาะ Hb ที่ถูก CO จับ ไม่ได้วัด cyanide — พิษ cyanide ใช้ lactate ที่สูงมาก (ราว 8–10 mmol/L ขึ้นไป) ร่วมกับอาการเป็นตัวชี้แทน · ไม่มีสถานการณ์ใดที่ระดับ COHb ยืนยันพิษ cyanide ได้ เพราะเป็นสารคนละตัว แม้ทั้งสองมักเกิดพร้อมกันจากควันไฟที่เผาพลาสติก'},
 trap='เห็นคำว่าไฟไหม้ร่วมกับ COHb ที่สูงกว่าค่าปกติตามตำรา (1–3%) แล้วรีบสรุปว่าเป็นพิษ CO · วิธีแยก: ถามประวัติสูบบุหรี่ก่อนแปลเสมอ — ผู้สูบจัดมีค่าพื้นฐานได้ถึงราว 10% ระดับต่ำกว่านี้ที่ไม่มีอาการจึงอธิบายได้ด้วยบุหรี่ ส่วนคนไม่สูบบุหรี่ที่มีค่าเท่ากันแปลว่าสัมผัส CO จริง',
 summary=['COHb 0–10% = minimal symptoms พบได้ในผู้สูบจัด — 8% ที่ไม่มีอาการในผู้สูบบุหรี่อธิบายได้ด้วยบุหรี่',
  'ค่าพื้นฐาน: คนไม่สูบบุหรี่ราว 1–3% (CO จากการสลาย heme) · ผู้สูบบุหรี่ราว 5–10%',
  'เกณฑ์ผิดปกติที่ใช้บ่อย: คนไม่สูบบุหรี่ &gt;3–4% · ผู้สูบบุหรี่ &gt;10%',
  'แปล COHb ต้องดูประวัติสูบบุหรี่ + เวลาตั้งแต่สัมผัส + การได้ O2 ก่อนเจาะ',
  'ค่าต่ำหลังได้ O2 นานไม่ตัดพิษรุนแรงก่อนหน้า — ตัดสินความรุนแรงจากอาการเป็นหลัก',
  'ชีทหน้า 12: COHb ราวร้อยละ 10 เริ่มมีอาการเล็กน้อย · เกินร้อยละ 50 เสียชีวิต'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตารางสไลด์หน้า 27 และชีทหน้า 10 ระบุชัดว่า 0–10% พบบ่อยในผู้สูบจัดและมีอาการน้อย · ส่วนที่ต่างกันเล็กน้อย: ชีทหน้า 12 บอกว่าราวร้อยละ 10 เริ่มมีอาการเล็กน้อย ขณะที่ตารางจัด 10% ไว้ในช่วงแทบไม่มีอาการ — ความจริงคือรอยต่อนี้ไม่คมและขึ้นกับการปรับตัวของแต่ละคน · ACEP Clinical Policy 2017 เตือนว่า COHb ปกติหรือต่ำไม่ตัดพิษ CO หากเจาะช้าหรือได้ O2 มาก่อน จึงต้องแปลร่วมกับอาการเสมอ',
 mnemonic='<b>“สูบจัดได้ถึงสิบ — ไม่สูบแต่สูง = สัมผัส CO จริง”</b>',
 guide='ACEP Clinical Policy: Acute Carbon Monoxide Poisoning (Ann Emerg Med 2017;69:98–107); Practice recommendations in the diagnosis, management, and prevention of carbon monoxide poisoning (Am J Respir Crit Care Med 2012;186:1095–1101)',
 variants=['หญิงไม่สูบบุหรี่ทำงานในห้องเก็บของที่เปิดเครื่องปั่นไฟ ปวดศีรษะ COHb 7% → สูงเกินค่าพื้นฐาน บ่งว่าสัมผัส CO จริง ให้ O2 และหาแหล่ง CO',
  'เด็กหลายคนในบ้านเดียวกันปวดศีรษะ อาเจียนพร้อมกันในช่วงหน้าหนาว → คิดถึงพิษ CO จากเครื่องทำความร้อน วัด COHb ทุกคนในบ้าน',
  'ผู้ป่วยโรคเม็ดเลือดแดงแตกเรื้อรังไม่สูบบุหรี่ COHb 4% ไม่มีประวัติสัมผัสควัน → CO สร้างเพิ่มจากการสลาย heme ไม่ใช่พิษจากภายนอก'])

mk(Q, 64, [27, 31, 's10'],
 stem='Paramedics find a 50-year-old man comatose with slow, shallow breathing in a burning room. A COHb measured before any oxygen is most likely in which range?',
 opts=['40–50%','30–40%','10–20%','20–30%','Above 50%'],
 interp='ชายถูกพบในห้องที่ไฟไหม้ หมดสติ หายใจช้าและตื้น เจาะ COHb ก่อนได้ O2 → พิษ CO รุนแรงที่กดสมองและศูนย์หายใจ → ถามช่วงระดับ COHb ที่เข้ากับภาพนี้ และต้องเข้าใจว่าทำไมต้องเป็นค่าที่เจาะก่อนได้ O2',
 why='ตาราง COHb ให้ <b>40–50% = coma, respiratory depression</b> — Hb เกือบครึ่งใช้ขน O2 ไม่ได้ ร่วมกับ Hb ที่เหลือปล่อย O2 ยากจาก<b>กราฟเลื่อนซ้าย</b> และ CO กด <b>cytochrome oxidase</b> ทำให้สมองขาด O2 จนหมดสติ และก้านสมองที่คุมการหายใจทำงานลดลง · โจทย์ระบุว่าเจาะ<b>ก่อนได้ O2</b> เพราะ COHb ลดลงเร็วเมื่อได้ O2 (half-life 240 นาทีบนอากาศ เหลือ 30–40 นาทีบน O2 100%) ระดับที่วัดภายหลังจึงต่ำกว่าระดับสูงสุดและเทียบกับอาการได้ไม่ดี · การรักษา: หมดสติจากไฟไหม้ในที่ปิด = <b>เปิดทางเดินหายใจ ช่วยหายใจด้วย bag-mask และ O2 100% ทันที</b> แล้วใส่ท่อช่วยหายใจเพราะ GCS ต่ำและเสี่ยงทางเดินหายใจบวม ตรวจ lactate หาพิษ cyanide ร่วม และพิจารณา hyperbaric oxygen เมื่อทำได้โดยไม่ทำให้การดูแลแผลไหม้ล่าช้า · สไลด์หน้า 27 <b>"40–50%: Coma, respiratory depression"</b> และสไลด์หน้า 31 ลายมือ <b>"∴ ถ้าคนไข้มาจากไฟไหม้ใน closed space และ Glasgow &lt; 8 = ให้ 100% O2 ด่วน ⟶ ใช้ mask c̄ bag"</b>',
 wrong={
 'B':'30–40% ทำให้สับสน กระสับกระส่าย ผู้ป่วยยังตื่นและดิ้นได้ ยังไม่ถึงขั้นหมดสติหรือหายใจกดลง · จะถูกถ้าหญิงที่เดินออกจากอาคารที่ไฟไหม้ได้เองแต่พูดสับสน วุ่นวาย ไม่ร่วมมือ และเจาะ COHb ที่จุดเกิดเหตุก่อนได้ O2',
 'C':'10–20% ทำให้ปวดศีรษะ คลื่นไส้ ซึ่งเป็นอาการเริ่มต้นที่ผู้ป่วยยังรู้ตัวดีทุกอย่าง ห่างจากภาพโคม่ามาก · จะถูกถ้าพนักงานที่ทำงานในห้องใต้ดินที่มีรถยกใช้น้ำมันวิ่งทั้งวัน มาด้วยปวดศีรษะตุบ ๆ และคลื่นไส้ตอนเย็น รู้ตัวดี และเจาะเลือดก่อนได้ O2',
 'D':'20–30% ทำให้ง่วงซึม อ่อนแรง ปลุกตื่นและตอบคำถามได้ ยังหายใจเองได้ดี · จะถูกถ้าชายที่นอนในห้องที่ตั้งเตาถ่านไว้ทั้งคืน ตื่นยาก ง่วงตลอด แขนขาอ่อนแรง แต่ปลุกแล้วตอบได้และหายใจปกติ',
 'E':'เกิน 50% เป็นระดับที่ตารางระบุว่าเสียชีวิต หัวใจหยุดเต้นจากขาด O2 ส่วนชายในโจทย์ยังหายใจเองได้แม้ช้าและตื้น · จะถูกถ้าผู้ประสบเหตุที่พบในห้องปิดที่ไฟไหม้ไม่มีชีพจรและไม่หายใจตั้งแต่ทีมกู้ภัยไปถึง แล้ววัด COHb ได้ 60%'},
 trap='ภาพหมดสติชวนให้เลือก &gt;50% ว่าเป็นระดับรุนแรงที่สุด หรือคิดว่า 30–40% พอแล้วเพราะเป็นอาการทางสมองเหมือนกัน · วิธีแยก: ยังหายใจเองได้ = ยังไม่ถึงระดับตาย (&gt;50%) · ปลุกไม่ตื่นร่วมกับหายใจกด = 40–50% · ตื่นแต่สับสน = 30–40% และต้องใช้ค่าที่เจาะก่อนได้ O2 เท่านั้น',
 summary=['โคม่า + หายใจกดลง = COHb 40–50% · สับสน = 30–40% · เกิน 50% = ตาย',
  'ค่าที่ใช้เทียบตารางต้องเป็นค่าก่อนได้ O2 — O2 100% ลด half-life จาก 240 นาทีเหลือ 30–40 นาที',
  'ลายมือหน้า 31: มาจาก closed space + Glasgow &lt; 8 → O2 100% ด่วนด้วย mask with bag',
  'หมดสติจากไฟไหม้ → ช่วยหายใจ ใส่ท่อเมื่อ GCS ≤ 8 ให้ FiO2 1.0',
  'หาสาเหตุร่วมของการหมดสติ: พิษ cyanide (lactate สูงมาก) · ทางเดินหายใจอุดกั้น · บาดเจ็บศีรษะ',
  'หมดสติจาก CO เป็นข้อบ่งชี้หลักของ hyperbaric oxygen ถ้าทำได้โดยไม่ทำให้การรักษาแผลไหม้ล่าช้า'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงตามตารางสไลด์หน้า 27 และชีทหน้า 10 และลายมือสไลด์หน้า 31 สนับสนุนการให้ O2 100% ทันทีในผู้ป่วย closed space ที่ Glasgow &lt; 8 · ในทางปฏิบัติ ผู้ป่วยหมดสติที่มาถึงโรงพยาบาลมักวัดได้ต่ำกว่าช่วงนี้เพราะได้ O2 ระหว่างทาง · UHMS (2019) และ ACEP (2017) ถือว่าการหมดสติเป็นตัวบ่งพิษรุนแรงที่ควรพิจารณา hyperbaric oxygen แต่ในผู้ป่วยแผลไหม้กว้าง การย้ายเข้าห้องปรับความดันต้องชั่งกับความเสี่ยงด้าน resuscitation และทางเดินหายใจ',
 mnemonic='<b>“สี่สิบหลับ ห้าสิบลา”</b>',
 guide='UHMS Hyperbaric Oxygen Therapy Indications 14th ed. (2019); Advanced Burn Life Support Provider Manual (American Burn Association 2018) — Inhalation injury',
 variants=['ชายหมดสติจากไฟไหม้โรงงานพลาสติก COHb 15% แต่ lactate 14 mmol/L ความดันต่ำ → CO อธิบายการหมดสติไม่พอ สงสัยพิษ cyanide ให้ hydroxocobalamin 5 g IV',
  'ชายหมดสติที่เกิดเหตุแต่ฟื้นแล้วเมื่อถึงโรงพยาบาล → ประวัติหมดสติยังเป็นเหตุให้พิจารณา hyperbaric oxygen แม้ตื่นดีแล้ว',
  'ชายโคม่าจากไฟไหม้ในห้องปิด มีรูม่านตาไม่เท่ากันและแผลที่ศีรษะ → ต้อง CT สมองหาเลือดออก ไม่ยกการหมดสติให้ CO อย่างเดียว'])

mk(Q, 65, [28, 29, 's11', 's12'],
 stem='A 38-year-old man is intubated after a closed-space fire. Black particulate material is suctioned from his endotracheal tube. Which investigation best confirms and grades lower airway injury?',
 opts=['Serum lactate','Fiberoptic bronchoscopy','Pulmonary function test','Chest radiograph on arrival','Pulse oximetry'],
 interp='ไฟไหม้ในที่ปิด ใส่ท่อช่วยหายใจแล้ว ดูดได้เขม่าดำจากท่อ (carbonaceous sputum) → สงสัย inhalation injury จากละอองเถ้า → ถามการตรวจที่ทั้งยืนยันและจัดระดับความรุนแรงของการบาดเจ็บทางเดินหายใจส่วนล่าง ต้องรู้ว่าการตรวจใดมองเห็นเยื่อบุหลอดลมโดยตรง',
 why='การวินิจฉัย inhalation injury เริ่มจาก<b>ประวัติไฟไหม้ในที่ปิด</b> และตรวจพบ <b>facial burn, carbonaceous sputum, respiratory compromise</b> แต่ทั้งหมดเป็นเพียงตัวบ่ง — การตรวจที่<b>ยืนยัน</b>คือ <b>fiberoptic bronchoscopy</b> ซึ่งมองเห็นเยื่อบุหลอดลมโดยตรง: เขม่าเกาะ เยื่อบุแดง บวม มีเลือดออก ตุ่มพอง เป็นแผล หรือเยื่อบุลอกหลุด และใช้<b>จัดระดับ</b>ได้ด้วย Abbreviated Injury Score (เกรด 0–4 จากไม่มีรอยโรคจนถึงเยื่อบุตายหลุดอุดหลอดลม) ซึ่งเกรดสูงสัมพันธ์กับการช่วยหายใจนานและอัตราตายสูง · ข้อดีอีกข้อคือ<b>ดูดล้างเขม่าและเสมหะออกได้ในการส่องครั้งเดียวกัน</b> · ทางเลือกอื่นคือ <b>Xenon-133 ventilation scan</b> ที่ดูการค้างของสารรังสีในหลอดลมเล็ก (ค้างนานกว่าราว 90 วินาทีบ่งว่าบาดเจ็บ) แต่ต้องย้ายผู้ป่วยวิกฤต จึงไม่สะดวกในระยะเฉียบพลัน · CXR แรกรับมักปกติ ส่วน lactate และ SpO2 ไม่จำเพาะ · ชีทหน้า 12 <b>"การยืนยันการวินิจฉัยสามารถทำได้ด้วยการส่องกล้องตรวจ(bronchoscopy)ซึ่งหัตถการนี้ยังใช้เป็นการรักษาไปพร้อมกันได้ด้วย"</b>',
 wrong={
 'A':'Lactate บอกภาวะเนื้อเยื่อขาด O2 จาก perfusion ไม่พอ พิษ CO หรือพิษ cyanide (ระดับสูงมากในผู้ป่วยไฟไหม้ชวนคิดถึง cyanide) แต่ไม่ได้มองเห็นหลอดลม · ไม่มีสถานการณ์ใดที่ serum lactate ยืนยันหรือจัดระดับการบาดเจ็บของทางเดินหายใจส่วนล่างได้ เพราะเป็นค่าเมตาบอลิกของทั้งร่างกาย ไม่บอกตำแหน่งหรือความลึกของรอยโรคในหลอดลม',
 'C':'การตรวจสมรรถภาพปอดต้องให้ผู้ป่วยตื่น ร่วมมือ และหายใจเข้าออกเต็มที่ ทำไม่ได้ในผู้ป่วยใส่ท่อระยะเฉียบพลัน และไม่ได้มองเห็นเยื่อบุ · ไม่มีสถานการณ์ใดที่ PFT ยืนยันและจัดระดับ inhalation injury ระยะแรกได้ เพราะใช้วัดผลระยะยาว เช่น หลอดลมตีบหรือ obstructive defect หลายเดือนหลังหาย',
 'D':'CXR แรกรับมีประโยชน์เป็นภาพตั้งต้นและหาภาวะร่วม แต่ในชั่วโมงแรกมักปกติแม้หลอดลมบาดเจ็บมาก ฝ้าหรือ atelectasis มักขึ้นภายหลังหลายวัน · ไม่มีสถานการณ์ใดที่ CXR แรกรับยืนยันและจัดระดับการบาดเจ็บของเยื่อบุหลอดลมได้ เพราะภาพรังสีไม่เห็นเยื่อบุโดยตรงและไวต่อรอยโรคระยะแรกต่ำ',
 'E':'Pulse oximetry วัดความอิ่มตัวของ Hb ด้วยแสงที่ปลายนิ้ว บอกได้แค่ภาวะ O2 ต่ำในภาพรวม และยังอ่านค่าสูงลวงในพิษ CO · ไม่มีสถานการณ์ใดที่ pulse oximetry ยืนยันหรือจัดระดับการบาดเจ็บของทางเดินหายใจส่วนล่างได้ เพราะไม่ให้ข้อมูลตำแหน่ง ขอบเขต หรือความรุนแรงของรอยโรคในหลอดลม'},
 trap='CXR และ SpO2 ทำได้เร็วข้างเตียงจึงดูเป็นตัวเลือกแรก และ lactate ก็สูงในผู้ป่วยไฟไหม้หนัก · วิธีแยก: คำถามขอทั้ง “ยืนยัน” และ “จัดระดับ” ซึ่งต้องเป็นการตรวจที่มองเห็นเยื่อบุหลอดลมโดยตรง มีเพียง bronchoscopy ที่ทำได้ และยังดูดล้างเขม่าได้พร้อมกัน',
 summary=['ยืนยันและจัดระดับ inhalation injury ส่วนล่าง = fiberoptic bronchoscopy ซึ่งดูดล้างได้ในครั้งเดียวกัน',
  'สไลด์หน้า 29: History closed space · PE facial burns, carbonaceous sputum, respiratory compromise · Investigation bronchoscopy, ventilation scanning',
  'สิ่งที่เห็นในกล้อง: เขม่า · เยื่อบุแดงบวม · เลือดออก · แผล · เยื่อบุลอกหลุด — จัดเกรด 0–4 ตาม Abbreviated Injury Score',
  'Xenon-133 ventilation scan: สารรังสีค้างในปอดนานกว่าราว 90 วินาที = หลอดลมเล็กบาดเจ็บ · ไม่สะดวกในระยะเฉียบพลัน',
  'CXR แรกรับมักปกติ · PFT ใช้ติดตามระยะยาว · lactate สูงมากชวนคิดถึง cyanide',
  'เขม่าในท่อ (สไลด์หน้า 28) บ่งว่าสูดควันจริง — ชีทหน้า 11 ระบุว่าพบได้ตั้งแต่บาดเจ็บเล็กน้อยจนถึงรุนแรง'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — สไลด์หน้า 29 จัด bronchoscopy เป็นการตรวจหลัก และชีทหน้า 12 ระบุว่าใช้ยืนยันและรักษาได้พร้อมกัน ตรงกับ ISBI Practice Guidelines 2016 และ ABLS 2018 ที่ให้ bronchoscopy เป็นมาตรฐานการวินิจฉัย · ข้อจำกัดที่ควรรู้: เกรดจากกล้องสัมพันธ์กับผลลัพธ์ไม่สม่ำเสมอในทุกการศึกษา และเห็นได้เฉพาะหลอดลมใหญ่ ไม่เห็นถุงลม · การส่องกล้องในผู้ป่วยที่ O2 ต่ำมากหรือความดันไม่คงที่มีความเสี่ยง ต้องชั่งเป็นราย · ventilation scan ปัจจุบันแทบไม่ใช้ในทางปฏิบัติ',
 mnemonic='<b>“อยากรู้ว่าหลอดลมไหม้แค่ไหน ต้องส่องเข้าไปดู — Bronch = See + Grade + Clean”</b>',
 guide='ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021) — Inhalation injury; Inhalation injury, pulmonary perturbations, and fluid resuscitation (J Burn Care Res 2007;28:80–83)',
 variants=['หญิงเสียงแหบหลังไฟไหม้หน้า ยังไม่ใส่ท่อและหายใจได้ → ส่อง nasopharyngolaryngoscopy ดูกล่องเสียงบวม เพื่อตัดสินใจใส่ท่อก่อนบวมมากขึ้น',
  'ชายส่องกล้องพบเยื่อบุหลอดลมหลุดลอกเป็นแผ่นและหลอดลมอุดเกือบทั้งหมด → เกรด 4 เสี่ยงช่วยหายใจนานและตายสูง เตรียมดูดล้างซ้ำ',
  'ผู้ป่วยไฟไหม้ความดันต่ำและ O2 ต่ำมากจนต้องใช้ FiO2 1.0 กับ PEEP สูง → เลื่อนการส่องกล้องจนกว่าจะคงที่ ใช้ประวัติและตรวจร่างกายนำการรักษาไปก่อน'])

mk(Q, 66, [23, 29, 's11'],
 stem='A 33-year-old woman has burns of both arms. Which detail in her history most strongly raises suspicion of inhalation injury?',
 opts=['Escaping by jumping from a first-floor window','Being trapped in a smoke-filled closed room','A facial sunburn the previous week','A scald from hot tap water over the chest','Burns of both soles from walking on hot sand'],
 interp='ผู้ป่วยมีแผลไหม้ที่แขนสองข้าง ยังไม่มีข้อมูลทางเดินหายใจ → ถามว่าประวัติการบาดเจ็บแบบใดทำให้สงสัย inhalation injury มากที่สุด ต้องใช้หลักว่าความเสี่ยงขึ้นกับการสูดควันและก๊าซร้อนในพื้นที่ที่ระบายอากาศไม่ได้และระยะเวลาที่สัมผัส',
 why='Inhalation injury เกิดจาก 3 กลไก: <b>พิษ CO</b>, <b>ความร้อนโดยตรงต่อทางเดินหายใจส่วนบน</b> และ <b>สารเคมีจากละอองเถ้า (products of combustion)</b> — ทั้งสามต้องอาศัยการสูดควันหรือก๊าซร้อนเข้าไป · ในห้องปิด ควัน ก๊าซร้อน CO และสารพิษอย่าง aldehyde สะสมเข้มข้นขึ้นเรื่อย ๆ ผู้ที่<b>ติดอยู่ในที่ปิด</b>จึงสูดเข้าไปปริมาณมากและนาน ประวัติ <b>burn in a closed space</b> จึงเป็นตัวบ่งทางประวัติที่สำคัญที่สุด ปัจจัยเสริมคือ ติดอยู่นาน หมดสติที่เกิดเหตุ และไฟจากวัสดุสังเคราะห์ · อย่างไรก็ตาม <b>ที่โล่งก็เกิดได้</b> เช่น เปลวไฟพุ่งใส่หน้าจากการระเบิด และการไม่มีประวัตินี้ลดโอกาสแต่ไม่ตัดออก · เมื่อสงสัยแล้วต้องตรวจหาแผลไหม้ที่หน้า ขนจมูกไหม้ เขม่าในปาก เสียงแหบ stridor และให้ O2 100% ทันที · สไลด์หน้า 23 ลายมือ <b>"key ┬ 1. Hx ⟶ closed space เสี่ยงกว่า <u>แต่</u> opened space ก็เกิดได้"</b>',
 wrong={
 'A':'การกระโดดหนีบอกความเสี่ยงบาดเจ็บร่วม เช่น กระดูกหัก บาดเจ็บศีรษะหรือกระดูกสันหลัง และแสดงว่าออกจากควันได้ ไม่ได้บอกว่าสูดควันมาก · ไม่มีสถานการณ์ใดที่การกระโดดหนีเองเป็นตัวเพิ่มความสงสัย inhalation injury เพราะความเสี่ยงมาจากการสูดควันก่อนหนี ซึ่งต้องถามเพิ่มว่าติดอยู่ในห้องที่มีควันนานเท่าไร',
 'C':'แดดเผาเป็นแผลไหม้ระดับตื้นจากรังสี UV ที่ผิวหนัง ไม่มีควัน ก๊าซร้อน หรือสารพิษผ่านเข้าทางเดินหายใจ และเกิดก่อนเหตุนี้หลายวัน · ไม่มีสถานการณ์ใดที่แดดเผาที่หน้าเพิ่มความเสี่ยง inhalation injury เพราะกลไกการบาดเจ็บทั้งสามแบบต้องอาศัยการสูดควันหรือไอร้อนเข้าไป ไม่ใช่รังสีบนผิว',
 'D':'น้ำร้อนจากก๊อกเป็น scald จากของเหลวที่ทำร้ายเฉพาะผิวที่สัมผัส ไม่มีไอหรือควันเข้าทางเดินหายใจ · ไม่มีสถานการณ์ใดที่น้ำร้อนลวกหน้าอกเพิ่มความเสี่ยง inhalation injury เพราะของเหลวไม่ถูกสูดเข้าไป — ต่างจากไอน้ำร้อนในห้องปิด ซึ่งพาความร้อนได้มากกว่าอากาศหลายพันเท่าและลงถึงหลอดลมส่วนล่างได้',
 'E':'ทรายร้อนทำให้เกิด contact burn ที่ฝ่าเท้า ซึ่งอยู่ไกลจากทางเดินหายใจและไม่มีควันหรือก๊าซเกี่ยวข้อง · ไม่มีสถานการณ์ใดที่แผลไหม้จากการสัมผัสทรายร้อนที่ฝ่าเท้าเพิ่มความเสี่ยง inhalation injury เพราะไม่มีการสูดสิ่งใดเข้าไป ความสำคัญของแผลนี้อยู่ที่ฝ่าเท้าเป็นบริเวณพิเศษที่ควรส่งต่อศูนย์ burn'},
 trap='ช้อย A มีเหตุไฟไหม้อาคารเหมือนกันจึงดูเกี่ยวข้อง ส่วนช้อยอื่นเป็นแผลไหม้ที่ไม่ผ่านทางเดินหายใจ · วิธีแยก: ถามว่าผู้ป่วย “สูด” อะไรเข้าไป นานแค่ไหน ในพื้นที่ปิดหรือไม่ — การติดอยู่ในห้องปิดที่มีควันตอบครบทั้งสามข้อ ส่วนการกระโดดหนีบอกแค่กลไกการบาดเจ็บร่วม',
 summary=['ประวัติที่บ่ง inhalation injury มากที่สุด = burn in a closed space คือติดอยู่ในห้องปิดที่มีควัน',
  'ปัจจัยเสริม: ติดอยู่นาน · หมดสติที่เกิดเหตุ · ไฟจากพลาสติกหรือวัสดุสังเคราะห์ · ไอน้ำร้อนในที่ปิด',
  'ที่โล่งก็เกิดได้ (ลายมือหน้า 23) — ไม่มีประวัติที่ปิดลดโอกาสแต่ไม่ตัดออก (ชีทหน้า 11)',
  'ตรวจร่างกายที่บ่ง: แผลไหม้หน้าและคอ · ขนจมูกขนตาไหม้ · เขม่าในคอ · carbonaceous sputum · เสียงแหบ stridor',
  'กลไก 3 แบบ: CO · ความร้อนโดยตรงต่อทางเดินหายใจส่วนบน · สารเคมีจากละอองเถ้าซึ่งพบบ่อยที่สุด',
  'ประวัติที่ปิด = ให้ O2 100% และวัด COHb ทันที แม้ยังไม่มีอาการ'],
 opinion='เห็นด้วยกับคำตอบ B ความมั่นใจสูง — ลายมือสไลด์หน้า 23 สไลด์หน้า 29 และชีทหน้า 11 ใช้ประวัติ closed space เป็นตัวบ่งแรก ตรงกับ ABLS 2018 ที่ถือว่าไฟไหม้ในที่ปิดเป็นปัจจัยเสี่ยงหลัก · ข้อสังเกต: ชีทหน้า 11 ระบุถูกต้องว่าแม้ไม่มีประวัตินี้ก็ยังเกิดได้ และแนวทางปัจจุบันไม่ใช้ประวัติอย่างเดียววินิจฉัย ต้องใช้การตรวจร่างกายและ bronchoscopy ยืนยัน · ประวัติที่ปิดยังใช้ตัดสินใจให้ O2 100% และวัด COHb ทันที แม้ผู้ป่วยไม่มีอาการ',
 mnemonic='<b>“ห้องปิด ควันขัง ติดนาน = สูดเต็มปอด”</b>',
 guide='Advanced Burn Life Support Provider Manual (American Burn Association 2018) — Airway management and smoke inhalation injury; Diagnosis and management of inhalation injury: an updated review (Crit Care 2015;19:351)',
 variants=['ชายติดอยู่ในรถที่ไฟลุกหลังชนนาน 10 นาที แผลไหม้แค่ที่ขา → ยังต้องสงสัย inhalation injury เพราะห้องโดยสารเป็นที่ปิดที่เต็มไปด้วยควันพลาสติก',
  'หญิงสูงอายุถูกพบหมดสติในห้องนอนที่มีควันแต่แทบไม่มีแผลไหม้ → เสี่ยงพิษ CO และ cyanide สูง ให้ O2 100% และตรวจ lactate',
  'ชายถูกไฟไหม้ร้านค้าแต่วิ่งออกมาได้ในไม่กี่วินาที ไม่มีแผลที่หน้าและไม่มีเขม่า → โอกาส inhalation injury ต่ำ สังเกตอาการและตรวจซ้ำ ไม่ต้องใส่ท่อป้องกัน'])

mk(Q, 67, [30, 's12', 's13'],
 stem='A 41-year-old man with confirmed smoke inhalation injury is intubated in the burn unit. Which combination is the standard supportive treatment?',
 opts=['100% oxygen, positive-pressure ventilation with PEEP and pulmonary toilet','Prophylactic systemic antibiotics and high-dose steroids to reduce airway edema','Immediate tracheostomy and lobectomy','Hyperventilation to a PaCO2 of 20 mm Hg','Fluid restriction and diuretics'],
 interp='inhalation injury ที่ยืนยันแล้ว ใส่ท่อช่วยหายใจอยู่ → ถามชุดการรักษาประคับประคองมาตรฐาน ต้องรู้ว่าไม่มียารักษาเฉพาะ หลักคือช่วยหายใจ ให้ O2 รักษาถุงลมไม่ให้แฟบ และเอาเขม่ากับเสมหะออก แล้วรอปอดหายเอง',
 why='การบาดเจ็บจากละอองเถ้าทำให้เกิด <b>chemical injury</b> ต่อหลอดลม: หลอดลมหดเกร็ง เสมหะมาก cilia เสียหน้าที่ เยื่อบุหลุดลอกรวมกับ fibrin เป็น cast อุดหลอดลม ถุงลมแฟบ และอาจลุกลามเป็น ARDS กับปอดอักเสบ · <b>ไม่มียารักษาเฉพาะ</b> การรักษาจึงเป็น supportive: <b>ใส่ท่อ</b>กันทางเดินหายใจส่วนบนอุดกั้น · <b>O2 100%</b> ไล่ CO · <b>positive-pressure ventilation with PEEP</b> เปิดถุงลมที่แฟบ (ปัจจุบันใช้แบบ lung-protective: tidal volume ราว 6 mL/kg ของน้ำหนักในอุดมคติ คุม plateau pressure ไม่เกิน 30 cmH2O) · <b>pulmonary toilet</b> ดูดเสมหะสม่ำเสมอ กายภาพทรวงอก พลิกตัว และ bronchoscopy ซ้ำ ซึ่งชีทถือเป็นหัวใจของการรักษาเท่ากับเครื่องช่วยหายใจ · สิ่งที่<b>ต้องหลีกเลี่ยง</b>: สเตียรอยด์ (เพิ่มการติดเชื้อ) ยาฆ่าเชื้อป้องกัน (เพิ่มเชื้อดื้อยา) และการจำกัดน้ำ — ผู้ป่วยที่มี inhalation injury มักต้องการสารน้ำ<b>มากกว่า</b>สูตรคำนวณ · ชีทหน้า 12 <b>"ผู้ป่วยจะต้องได้รับการดูแลกำจัดเสมหะและสิ่งคัดหลั่งต่างๆในระบบทางเดินหายใจอย่างดีและสม่ำเสมอซึ่งวิธีนี้ถือเป็นหัวใจของการรักษา"</b>',
 wrong={
 'B':'ยาฆ่าเชื้อป้องกันไม่ลดปอดอักเสบแต่คัดเลือกเชื้อดื้อยา และสเตียรอยด์เพิ่มการติดเชื้อในผู้ป่วยไฟไหม้ ชีทจึงให้หลีกเลี่ยงสเตียรอยด์ · ไม่มีสถานการณ์ใดที่ยาฆ่าเชื้อป้องกันร่วมกับสเตียรอยด์ขนาดสูงเป็นการรักษาประคับประคองมาตรฐานของ inhalation injury เพราะยาฆ่าเชื้อใช้เมื่อเกิดปอดอักเสบจริงตามผลเพาะเชื้อ',
 'C':'การเจาะคอใช้ในผู้ป่วยที่คาดว่าต้องช่วยหายใจนานหลายสัปดาห์ และทำภายหลังเมื่อพร้อม ส่วนการตัดกลีบปอดไม่มีบทบาท เพราะการบาดเจ็บกระจายทั่วหลอดลมทั้งสองข้าง · ไม่มีสถานการณ์ใดที่เจาะคอทันทีร่วมกับตัดกลีบปอดเป็นชุดการรักษาประคับประคองมาตรฐาน เพราะผู้ป่วยใส่ท่อทางปากได้อยู่แล้ว และปอดที่บาดเจ็บหายเองได้เมื่อประคับประคองดี',
 'D':'การหายใจเร็วจน PaCO2 ต่ำมากเคยใช้ลดความดันในกะโหลกชั่วคราว ทำให้หลอดเลือดสมองหดจนสมองขาดเลือด และต้องใช้ปริมาตรลมหรือความดันสูงซึ่งยิ่งทำร้ายปอดที่บาดเจ็บ · ไม่มีสถานการณ์ใดที่ตั้งเป้า PaCO2 20 mm Hg เป็นการรักษามาตรฐานของ inhalation injury เพราะแนวทางปัจจุบันใช้ lung-protective ventilation ที่ยอมให้ PaCO2 สูงขึ้นได้ (permissive hypercapnia)',
 'E':'การจำกัดน้ำและให้ยาขับปัสสาวะใช้กับปอดบวมน้ำจากหัวใจหรือน้ำเกิน ส่วนปอดบวมใน inhalation injury เกิดจากหลอดเลือดรั่วจากสารเคมี และผู้ป่วยกลุ่มนี้ต้องการสารน้ำมากกว่าสูตรคำนวณ · ไม่มีสถานการณ์ใดในช่วง resuscitation ที่การจำกัดน้ำร่วมกับยาขับปัสสาวะเป็นการรักษามาตรฐาน เพราะทำให้ช็อก ไตวาย และ zone of stasis ตายเพิ่ม — ปรับสารน้ำตามปัสสาวะแทน'},
 trap='ช้อย B ฟังเป็นการ “ป้องกัน” ที่สมเหตุผล คือกันติดเชื้อและลดบวม ส่วนช้อย E ฟังเหมือนกันปอดบวมน้ำ · วิธีแยก: inhalation injury ไม่มียาเฉพาะ ทุกอย่างที่เป็นมาตรฐานคือการพยุงหน้าที่ปอด (O2, PEEP, ดูดเสมหะ) จนเยื่อบุหายเอง ส่วนยาและการจำกัดน้ำเพิ่มภาวะแทรกซ้อน',
 summary=['มาตรฐาน = ใส่ท่อ + O2 100% + positive-pressure ventilation with PEEP + pulmonary toilet ด้วย bronchoscopy',
  'ชีทหน้า 13: หลีกเลี่ยงสเตียรอยด์ · Swan-Ganz อาจจำเป็นในผู้ที่มีโรคหัวใจหรือปอดร่วม · HFPV อาจมีประโยชน์',
  'Lung-protective ventilation: tidal volume ราว 6 mL/kg ของน้ำหนักในอุดมคติ · plateau ≤ 30 cmH2O · ยอมให้ CO2 สูงได้',
  'Pulmonary toilet: ดูดเสมหะสม่ำเสมอ · กายภาพทรวงอก · พลิกตัว ลุกเดินเร็ว · bronchoscopy ซ้ำเมื่ออุด',
  'บางศูนย์พ่น heparin ร่วม N-acetylcysteine และยาขยายหลอดลม เพื่อลด cast และหลอดลมหดเกร็ง — หลักฐานยังไม่แน่น',
  'inhalation injury → ต้องการสารน้ำมากกว่าสูตรคำนวณ ไม่จำกัดน้ำ · ยาฆ่าเชื้อให้เมื่อปอดอักเสบจริงตามผลเพาะเชื้อ'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงกับสไลด์หน้า 30 และชีทหน้า 12–13 รวมถึง ISBI Practice Guidelines 2016 ที่ไม่แนะนำสเตียรอยด์และยาฆ่าเชื้อป้องกัน · จุดที่ต่างจากแนวปัจจุบัน: สไลด์หน้า 30 ใส่ Swan-Ganz catheter ไว้ในหมวด Monitoring แต่ปัจจุบันแทบไม่ใช้ประจำ เพราะไม่ช่วยผลลัพธ์และมีภาวะแทรกซ้อน หันไปใช้ปัสสาวะ ultrasound หรือ transpulmonary thermodilution แทน · PEEP บนสไลด์ควรใช้ร่วมกับ tidal volume ต่ำตามการศึกษา ARDS Network (2000) ซึ่งสไลด์ไม่ได้กล่าวถึง · HFPV ที่ชีทหน้า 13 กล่าวถึงยังเป็นทางเลือกในบางศูนย์ ไม่ใช่มาตรฐาน',
 mnemonic='<b>“Tube – O2 – PEEP – Toilet: พยุงไว้ ไม่มียาวิเศษ”</b>',
 guide='ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Ventilation with lower tidal volumes as compared with traditional tidal volumes for acute lung injury and ARDS (N Engl J Med 2000;342:1301–1308)',
 variants=['ชายใส่ท่อจาก inhalation injury วันที่ 2 PaO2/FiO2 120 ภาพปอดฝ้าสองข้าง → ARDS ใช้ tidal volume 6 mL/kg ของน้ำหนักในอุดมคติ เพิ่ม PEEP และพิจารณานอนคว่ำ',
  'ผู้ป่วยไฟไหม้ 40% TBSA ร่วม inhalation injury ปัสสาวะออกน้อยแม้ให้ตาม Parkland → เพิ่มสารน้ำตามปัสสาวะ เพราะ inhalation injury ทำให้ต้องการน้ำมากขึ้น',
  'ชายมีหัวใจล้มเหลวเดิมร่วม inhalation injury ปรับสารน้ำยากเพราะปอดบวมและความดันต่ำสลับกัน → ใช้ invasive hemodynamic monitoring ช่วยปรับสารน้ำ'])

mk(Q, 68, [30, 31, 's12'],
 stem='A 30-year-old man with a COHb of 25% after a house fire is given 100% oxygen by non-rebreather mask. What is the main purpose of this therapy?',
 opts=['To displace carbon monoxide from hemoglobin and shorten its half-life','To convert cyanide to thiocyanate in the liver','To prevent progressive swelling of the upper airway during resuscitation','To reduce the volume of resuscitation fluid needed','To dissolve soot deposited in the bronchi'],
 interp='ผู้ป่วยไฟไหม้บ้าน COHb 25% ได้ O2 100% ทาง non-rebreather mask → พิษ CO ระดับที่มีอาการ → ถามว่าการให้ O2 ความเข้มข้นสูงมีเป้าหมายหลักอะไร ต้องใช้หลักการแย่งจับ Hb ระหว่าง O2 กับ CO และผลต่อ half-life',
 why='CO จับ Hb แน่นกว่า O2 ราว <b>210 เท่า</b> แต่การจับนี้<b>ผันกลับได้</b> — ตามหลัก mass action เมื่อเพิ่มความเข้มข้นของ O2 ในถุงลมมาก ๆ O2 จะ<b>แย่งที่บน Hb และไล่ CO ออก</b>เร็วขึ้น · ผลคือ half-life ของ COHb ลดจาก <b>240 นาทีที่ FiO2 0.21</b> เหลือ <b>30–40 นาทีที่ FiO2 1.0</b> ตามสไลด์ และ O2 ที่ละลายในพลาสมาที่เพิ่มขึ้นช่วยส่ง O2 ให้เนื้อเยื่อระหว่างที่ Hb ยังถูกยึด · CO หลุดจาก Hb ก่อน แล้วจึงหลุดจาก <b>cytochrome oxidase</b> ใน mitochondria ภายหลัง ชีทจึงให้ O2 ต่อจน metabolic acidosis หาย · non-rebreather mask ให้ FiO2 จริงราว 0.6–0.8 การใส่ท่อช่วยหายใจให้ FiO2 ใกล้ 1.0 กว่า · ให้ O2 ทันทีที่สงสัยโดยไม่รอผล COHb · สไลด์หน้า 30 ลายมือ <b>"ไล่ carboxy Hb"</b> และสไลด์หน้า 31 ลายมือ <b>"· ให้ 100% O2 ⟶ t1/2 ลดเหลือ 30 min"</b>',
 wrong={
 'B':'การเปลี่ยน cyanide เป็น thiocyanate ทำโดยเอนไซม์ rhodanese โดยใช้ sodium thiosulfate เป็นตัวให้ sulfur ส่วนยาแก้พิษหลักในผู้ป่วยไฟไหม้ปัจจุบันคือ hydroxocobalamin ที่จับ cyanide เป็น cyanocobalamin · ไม่มีสถานการณ์ใดที่ O2 100% ทำหน้าที่เปลี่ยน cyanide เป็น thiocyanate เพราะ O2 เป็นเพียงการรักษาประคับประคอง ไม่ใช่ตัวให้ sulfur',
 'C':'ทางเดินหายใจส่วนบนบวมจากความร้อนโดยตรงและบวมมากขึ้นหลังให้สารน้ำ การป้องกันการอุดกั้นคือใส่ท่อช่วยหายใจแต่เนิ่น ตามลายมือ “กัน upper airway obst.” · ไม่มีสถานการณ์ใดที่ O2 100% ป้องกันการบวมของทางเดินหายใจส่วนบนได้ เพราะ O2 ไม่ได้ลดการรั่วของหลอดเลือดหรือการบวมของเนื้อเยื่อ และ O2 ผ่าน mask ไม่ช่วยเมื่อทางเดินหายใจอุดแล้ว',
 'D':'ปริมาณสารน้ำในช่วง resuscitation คำนวณจาก %TBSA และน้ำหนักตัว แล้วปรับตามปัสสาวะ ผู้ป่วยที่มี inhalation injury ยังต้องการน้ำมากกว่าเดิมด้วย · ไม่มีสถานการณ์ใดที่ O2 100% ลดปริมาณสารน้ำที่ต้องให้ เพราะ O2 ไม่ได้ลดการรั่วของ capillary ซึ่งเป็นสาเหตุการเสียน้ำของแผลไหม้',
 'E':'เขม่าและสิ่งคัดหลั่งในหลอดลมเอาออกด้วย pulmonary toilet คือดูดเสมหะ กายภาพทรวงอก และ bronchoscopy ซ้ำ · ไม่มีสถานการณ์ใดที่ O2 100% ละลายเขม่าในหลอดลมได้ เพราะเขม่าเป็นอนุภาคคาร์บอนที่ไม่ทำปฏิกิริยากับ O2 ที่อุณหภูมิร่างกาย และ O2 แห้งยังทำให้เสมหะเหนียวขึ้นถ้าไม่ให้ความชื้น'},
 trap='ผู้ป่วยไฟไหม้ได้ O2 ด้วยหลายเหตุผล ทั้งทางเดินหายใจ cyanide และภาวะขาด O2 จึงชวนเลือกช้อยที่ฟังเป็นประโยชน์อื่น · วิธีแยก: โจทย์ให้ COHb 25% เป็นตัวเด่น เป้าหลักจึงเป็นการแย่งจับ Hb และลด half-life ส่วนการกันทางเดินหายใจบวมทำด้วยท่อ และ cyanide แก้ด้วยยาเฉพาะ',
 summary=['O2 100% ในพิษ CO = แย่งที่บน Hb ไล่ CO ออก ลด half-life (ลายมือหน้า 30: “ไล่ carboxy Hb”)',
  'half-life COHb: FiO2 0.21 → 240 นาที · FiO2 1.0 → 30–40 นาทีตามสไลด์ · hyperbaric 2.5–3 ATA → ราว 20–30 นาที',
  'CO หลุดจาก Hb ก่อน แล้วจึงหลุดจาก cytochrome oxidase — ชีทหน้า 12 ให้ O2 ต่อจนกรดในเลือดหาย',
  'non-rebreather mask ให้ FiO2 จริงราว 0.6–0.8 · ใส่ท่อให้ใกล้ 1.0 กว่า',
  'ให้ O2 ทันทีที่สงสัย ไม่รอผล COHb · ปัจจุบันให้จน COHb กลับปกติ (&lt; 3–5%, ผู้สูบบุหรี่ &lt; 10%) และอาการหาย',
  'กันทางเดินหายใจบวม = ใส่ท่อ · พิษ cyanide = hydroxocobalamin · เขม่า = pulmonary toilet'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงกับลายมือสไลด์หน้า 30 และ 31 และชีทหน้า 12 · จุดที่ต่างจากข้อมูลปัจจุบัน: half-life บน O2 100% ผ่าน mask ที่วัดจริงในผู้ป่วยเฉลี่ยราว 74 นาที (Chest 2000) ยาวกว่าที่สไลด์ให้ 30–40 นาที · ชีทหน้า 12 ใช้ bicarbonate มากกว่า 20 mEq/L เป็นจุดหยุด O2 ส่วนแนวทางปัจจุบันใช้ COHb ที่กลับปกติร่วมกับอาการที่หาย และถ้ากรดยังค้างทั้งที่ COHb ปกติแล้วให้คิดถึง cyanide · hyperbaric oxygen ลด half-life ได้อีก แต่ข้อบ่งชี้ขึ้นกับอาการทางสมองมากกว่าตัวเลข',
 mnemonic='<b>“O2 ท่วม Hb → CO หลุด: 240 → 30”</b>',
 guide='Carboxyhemoglobin half-life in carbon monoxide-poisoned patients treated with 100% oxygen at atmospheric pressure (Chest 2000;117:801–808); ACEP Clinical Policy: Acute Carbon Monoxide Poisoning (Ann Emerg Med 2017;69:98–107)',
 variants=['หญิงตั้งครรภ์ 30 สัปดาห์พิษ CO อาการดีขึ้นแล้ว → ให้ O2 100% นานกว่าผู้ใหญ่ทั่วไปและพิจารณา hyperbaric เพราะ Hb ของทารกจับ CO แน่นกว่าและขับออกช้ากว่า',
  'ผู้ป่วยพิษ CO ไม่รู้สึกตัว ใส่ท่อช่วยหายใจแล้ว → ตั้ง FiO2 1.0 บนเครื่องช่วยหายใจ ได้ O2 ใกล้ 100% มากกว่าการให้ทาง mask',
  'เด็กพิษ CO จากเตาถ่านปิ้งย่างในห้องปิด ปวดศีรษะ → ให้ O2 ความเข้มข้นสูงทันที และตรวจคนอื่นที่อยู่ในห้องเดียวกันด้วย เพราะสัมผัสแหล่งเดียวกัน'])

mk(Q, 69, [30, 's12'],
 stem='A man with severe smoke inhalation injury repeatedly plugs his airways with soot and mucosal casts. Which intervention clears them?',
 opts=['Repeated bronchoscopy','Open lung biopsy','Segmental tracheal resection','Talc pleurodesis','Bilateral chest tube insertion'],
 interp='inhalation injury รุนแรง เขม่าและแผ่นเยื่อบุที่หลุด (cast) อุดหลอดลมซ้ำ ๆ → ภาวะที่ต้องทำ pulmonary toilet → ถามหัตถการที่เข้าไปในหลอดลมเพื่อดูดล้างสิ่งอุดตันออก ต้องแยกหัตถการที่อยู่ในรูหลอดลมออกจากหัตถการทรวงอกอื่น',
 why='หลังสูดควัน เยื่อบุหลอดลมที่ถูกสารเคมีทำลายจะ<b>หลุดลอก</b> ผสมกับ fibrin เสมหะ และเขม่า กลายเป็น <b>cast</b> อุดหลอดลมเล็กและใหญ่ ร่วมกับ cilia เสียหน้าที่ทำให้ขับออกเองไม่ได้ → <b>ถุงลมแฟบ (atelectasis)</b> ความดันทางเดินหายใจสูง O2 ต่ำ และเป็นแหล่งของ<b>ปอดอักเสบ</b> · <b>Pulmonary toilet</b> คือการทำความสะอาดทางเดินหายใจ ได้แก่ ดูดเสมหะทางท่อสม่ำเสมอ กายภาพทรวงอก พลิกตัว ลุกเร็ว และเมื่อดูดธรรมดาไม่ออกหรือมีกลีบปอดแฟบ ใช้ <b>therapeutic bronchoscopy</b> ซ้ำ ซึ่งเห็นตำแหน่งอุดตันและดูดล้างได้โดยตรง · บางศูนย์ใช้พ่น heparin ร่วม N-acetylcysteine เพื่อลดการเกิด cast แต่ไม่แทนการดูดล้าง · ข้อควรระวังคือการส่องกล้องในผู้ป่วยที่ O2 ต่ำมากหรือความดันไม่คงที่อาจทำให้ทรุดลงชั่วคราว ต้องเพิ่ม FiO2 ก่อนทำ · สไลด์หน้า 30 <b>"Pulmonary Toilet - Broncoscopy"</b> และชีทหน้า 12 <b>"การทำการดูดเสมหะและตรวจด้วยกล้องอย่างสม่ำเสมอ(repeat bronchoscopy) อาจจำเป็นเพื่อทำความสะอาดทางเดินหายใจ"</b>',
 wrong={
 'B':'การตัดชิ้นเนื้อปอดแบบเปิดใช้วินิจฉัยโรคเนื้อปอดที่หาสาเหตุด้วยวิธีอื่นไม่ได้ เป็นการผ่าตัดใหญ่ที่ไม่ได้เข้าไปในหลอดลมหรือเอาสิ่งอุดตันออก · ไม่มีสถานการณ์ใดที่ open lung biopsy ใช้ดูดล้างเขม่าและ cast ออกจากหลอดลม เพราะเป็นหัตถการวินิจฉัยที่ตัดเนื้อปอดส่วนปลาย และเพิ่มความเสี่ยงลมรั่วในปอดที่บาดเจ็บ',
 'C':'การตัดต่อหลอดลมคอเป็นการผ่าตัดแก้หลอดลมตีบที่เกิดจากแผลเป็นภายหลัง เช่น หลังใส่ท่อนานหรือเจาะคอ ซึ่งเป็นภาวะแทรกซ้อนระยะยาว · ไม่มีสถานการณ์ใดที่ segmental tracheal resection ใช้เอาเขม่าและเสมหะออกในระยะเฉียบพลัน เพราะสิ่งอุดตันอยู่ในรูหลอดลมทั่วทั้งสองปอด เอาออกได้ด้วยการดูดล้างโดยไม่ต้องตัดหลอดลม',
 'D':'Pleurodesis คือการทำให้เยื่อหุ้มปอดสองชั้นติดกันเพื่อกัน effusion หรือ pneumothorax ที่เป็นซ้ำ ทำในช่องเยื่อหุ้มปอด ไม่เกี่ยวกับรูหลอดลม · ไม่มีสถานการณ์ใดที่ talc pleurodesis ช่วยเอาเขม่าหรือ cast ออกจากหลอดลม เพราะหัตถการนี้อยู่นอกปอด และ talc ยังทำให้เกิดการอักเสบที่อาจซ้ำเติมปอดที่บาดเจ็บ',
 'E':'สาย chest tube ระบายลมหรือของเหลวในช่องเยื่อหุ้มปอด ใช้เมื่อเกิด pneumothorax จากความดันของเครื่องช่วยหายใจหรือมีน้ำในช่องปอด · ไม่มีสถานการณ์ใดที่ chest tube สองข้างใช้เอาเขม่าและเสมหะออกจากหลอดลม เพราะสายอยู่นอกปอด ไม่มีทางเชื่อมกับรูหลอดลม'},
 trap='ทุกช้อยเป็นหัตถการทรวงอกที่ฟังจริงจัง และผู้ป่วยหนักชวนให้คิดว่าต้องผ่าตัดใหญ่ · วิธีแยก: ถามว่าสิ่งที่อุดอยู่ตรงไหน — เขม่าและ cast อยู่ในรูหลอดลม หัตถการที่ถูกต้องต้องเข้าไปทางหลอดลมแล้วดูดออก คือ bronchoscopy ส่วนช้อยอื่นอยู่ในเนื้อปอด ผนังหลอดลม หรือช่องเยื่อหุ้มปอด',
 summary=['Pulmonary toilet ที่เข้าไปดูดล้างเขม่าและ cast โดยตรง = repeat bronchoscopy',
  'ชีทหน้า 12: การกำจัดเสมหะและสิ่งคัดหลั่งสม่ำเสมอเป็นหัวใจของการรักษาเท่ากับการใช้เครื่องช่วยหายใจ',
  'Cast เกิดจากเยื่อบุหลุด + fibrin + เสมหะ + เขม่า → อุดหลอดลม ถุงลมแฟบ ปอดอักเสบ',
  'Pulmonary toilet พื้นฐาน: ดูดเสมหะทางท่อ · กายภาพทรวงอก · พลิกตัว · ลุกเดินเร็ว — bronchoscopy เมื่อดูดไม่ออกหรือกลีบปอดแฟบ',
  'เพิ่ม FiO2 ก่อนส่องกล้อง เพราะอาจทำให้ O2 ตกชั่วคราว',
  'Bronchoscopy ใช้ได้ทั้งวินิจฉัยและรักษาในการส่องครั้งเดียว'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงกับสไลด์หน้า 30 ที่จัด bronchoscopy ไว้ใต้ Pulmonary Toilet และชีทหน้า 12 ที่ให้ส่องกล้องดูดล้างซ้ำ · สอดคล้องกับ ISBI Practice Guidelines 2016 ที่แนะนำ therapeutic bronchoscopy เมื่อมี cast หรือกลีบปอดแฟบ · ข้อสังเกต: การส่องกล้องตามกำหนดทุกวันโดยไม่มีข้อบ่งชี้ยังไม่มีหลักฐานว่าดีกว่าการทำเมื่อจำเป็น และการพ่นยาละลายลิ่ม (heparin) ที่บางศูนย์ใช้ยังมีผลการศึกษาขัดกัน จึงยังไม่เป็นมาตรฐาน',
 mnemonic='<b>“อุดในท่อ เอาออกทางท่อ — Bronch ล้างห้องน้ำปอด (toilet)”</b>',
 guide='ISBI Practice Guidelines for Burn Care (Burns 2016;42:953–1021); Total Burn Care 5th ed. (2018) — Inhalation injury',
 variants=['ผู้ป่วย inhalation injury ใส่ท่อวันที่ 3 ปอดกลีบล่างซ้ายแฟบทันทีและ peak pressure สูงขึ้น → ส่องกล้องหาและดูด cast ที่อุดหลอดลมกลีบนั้น',
  'ผู้ป่วยไฟไหม้ใส่ท่อนาน 4 สัปดาห์ ถอดท่อแล้ว 2 เดือนต่อมามี stridor เวลาออกแรง → หลอดลมคอตีบจากแผลเป็น ส่องกล้องประเมินและพิจารณาขยายหรือผ่าตัดแก้',
  'ผู้ป่วยใส่ท่อจาก inhalation injury เกิด pneumothorax ขวาจากความดันเครื่องช่วยหายใจ → ใส่ chest tube ด้านขวา แล้วทำ pulmonary toilet ต่อ'])

mk(Q, 70, [31, 's12'],
 stem='A man with carbon monoxide poisoning is breathing room air only. What is the approximate half-life of his COHb?',
 opts=['About 240 minutes','Less than 10 minutes','About 30 minutes','About 24 hours','About 72 hours'],
 interp='ผู้ป่วยพิษ CO หายใจอากาศปกติเท่านั้น ไม่ได้ O2 เสริม → ถามค่า half-life ของ COHb ที่ FiO2 0.21 ต้องรู้ค่าการขับ CO ออกจาก Hb และเข้าใจว่าค่านี้ขึ้นกับความเข้มข้นของ O2 ที่หายใจเข้าไป',
 why='CO ออกจากร่างกายเกือบทั้งหมดทาง<b>ปอด</b>โดยไม่ถูกเปลี่ยนแปลง อัตราที่หลุดจาก Hb ขึ้นกับ<b>ความดัน O2 ในถุงลม</b>ที่มาแย่งที่ · ที่อากาศปกติ (<b>FiO2 0.21</b>) half-life ราว <b>240 นาที หรือราว 4 ชั่วโมง</b> หมายความว่าทุก 4 ชั่วโมง COHb ลดลงครึ่งหนึ่ง จากระดับอันตรายลงสู่ระดับปลอดภัยจึงกินเวลาหลายชั่วโมง ซึ่งนานเกินไปสำหรับสมองและหัวใจที่ขาด O2 · เมื่อให้ <b>FiO2 1.0</b> half-life ลดเหลือ <b>30–40 นาที</b> และ hyperbaric oxygen ลดได้อีก — นี่คือเหตุผลที่ต้องให้ O2 100% ทันทีที่สงสัย ไม่ปล่อยให้หายใจอากาศรอผล · ค่าจริงในผู้ป่วยแต่ละรายแปรปรวนได้กว้าง ขึ้นกับการหายใจ อายุ และระยะเวลาที่สัมผัส · ผลในทางปฏิบัติ: COHb ที่วัดได้หลังผู้ป่วยหายใจอากาศหรือได้ O2 มานาน จะต่ำกว่าระดับสูงสุดที่เกิดเหตุ · สไลด์หน้า 31 <b>"240 minutes at FiO2 0.21"</b> ลายมือ <b>"~4 hr"</b> และ <b>"= room air : O2 21%"</b>',
 wrong={
 'B':'ค่าที่สั้นกว่า 10 นาทีไม่ตรงกับการขับ CO ในสภาวะใดที่ความดันบรรยากาศ แม้ได้ O2 100% ยังใช้ 30–40 นาที และ hyperbaric oxygen ยังราว 20–30 นาที · ไม่มีสถานการณ์ใดที่ half-life ของ COHb ขณะหายใจอากาศปกติสั้นกว่า 10 นาที เพราะ O2 21% แย่ง CO ออกจาก Hb ได้ช้ากว่าการให้ O2 ความเข้มข้นสูงมาก',
 'C':'30 นาทีอยู่ในช่วง 30–40 นาที ซึ่งเป็นค่าเมื่อหายใจ O2 100% (FiO2 1.0) ไม่ใช่อากาศปกติ — เป็นช้อยที่ล่อคนที่จำตัวเลขได้แต่สลับเงื่อนไข · ไม่มีสถานการณ์ใดที่ half-life ขณะหายใจอากาศปกติสั้นเพียง 30 นาที เพราะค่าที่ FiO2 0.21 ยาวกว่าค่าที่ FiO2 1.0 ราว 6–8 เท่า',
 'D':'24 ชั่วโมงยาวกว่าค่าจริงราว 6 เท่า เป็นช้อยที่ล่อด้วยเลข 24 ที่คล้าย 240 — 240 นาทีเท่ากับ 4 ชั่วโมงเท่านั้น · ไม่มีสถานการณ์ใดที่ half-life ของ COHb ขณะหายใจอากาศปกติยาวถึง 24 ชั่วโมงในคนที่ยังหายใจได้ เพราะ CO ยังถูกไล่ออกทางปอดอย่างต่อเนื่องด้วย O2 21%',
 'E':'72 ชั่วโมงยาวกว่าค่าจริงราว 18 เท่า ถ้า half-life นานขนาดนี้ COHb จะคงสูงหลายวัน ซึ่งไม่ตรงกับผู้ป่วยที่ COHb กลับปกติภายในวันเดียว · ไม่มีสถานการณ์ใดที่ half-life ของ COHb ยาวถึง 72 ชั่วโมงขณะหายใจอากาศ เพราะการจับ CO บน Hb ผันกลับได้ และหลุดออกตามความดัน O2 ในถุงลมภายในหลักชั่วโมง'},
 trap='ตัวเลข 240 กับ 24 คล้ายกันจนอ่านสลับหน่วย และ 30–40 นาทีอยู่บรรทัดถัดไปบนสไลด์เดียวกัน · วิธีแยก: ดูเงื่อนไข FiO2 ในโจทย์ก่อน — อากาศปกติ (0.21) = 240 นาที ≈ 4 ชั่วโมง · O2 100% (1.0) = 30–40 นาที แล้วแปลงหน่วยให้ตรงก่อนเลือก',
 summary=['Half-life COHb ที่อากาศปกติ (FiO2 0.21) ≈ 240 นาที ≈ 4 ชั่วโมง',
  'FiO2 1.0 → 30–40 นาที ตามสไลด์และชีทหน้า 12 · hyperbaric oxygen → สั้นลงอีก',
  'ลายมือหน้า 31: “~4 hr” และ “= room air : O2 21%”',
  'หายใจอากาศรอผลทำให้ COHb ลดช้ามาก — ให้ O2 100% ทันทีที่สงสัย',
  'CO ถูกขับทางปอดเกือบทั้งหมดโดยไม่เปลี่ยนแปลง อัตราขึ้นกับความดัน O2 ในถุงลม',
  'COHb ที่วัดช้าหลังเกิดเหตุต่ำกว่าระดับสูงสุด — ใช้อาการประกอบเสมอ'],
 opinion='เห็นด้วยกับคำตอบ A ความมั่นใจสูง — ตรงตัวกับสไลด์หน้า 31 และชีทหน้า 12 · ข้อมูลจากผู้ป่วยจริงแสดงว่าค่าแปรปรวนกว้าง: ที่อากาศปกติรายงานไว้ราว 4–6 ชั่วโมง ส่วนบน O2 100% ผ่าน mask วัดได้เฉลี่ยราว 74 นาที (Chest 2000) ยาวกว่าที่สไลด์ให้ไว้ 30–40 นาที ตัวเลขบนสไลด์จึงเป็นค่าในสภาวะที่ดีที่สุด ในทางปฏิบัติอาจนานกว่า · หลักที่ต้องจำไม่เปลี่ยน: O2 ความเข้มข้นสูงลด half-life ลงหลายเท่า จึงต้องให้ทันทีที่สงสัย',
 mnemonic='<b>“อากาศ 4 ชั่วโมง · O2 ครึ่งชั่วโมง — 240 ไม่ใช่ 24”</b>',
 guide='Carboxyhemoglobin half-life in carbon monoxide-poisoned patients treated with 100% oxygen at atmospheric pressure (Chest 2000;117:801–808); Total Burn Care 5th ed. (2018) — Inhalation injury',
 variants=['ชายพิษ CO ถูกพบหลังเกิดเหตุ 4 ชั่วโมงโดยหายใจอากาศตลอด COHb วัดได้ 20% → ระดับขณะเกิดเหตุน่าจะราว 40% อาการตอนนั้นหนักกว่าที่เห็น',
  'ชุมชนห่างไกลไม่มี O2 ระหว่างขนส่งผู้ป่วยพิษ CO นาน 2 ชั่วโมง → COHb ลดลงยังไม่ถึงครึ่ง ต้องหา O2 ความเข้มข้นสูงให้เร็วที่สุด',
  'ผู้ป่วยพิษ CO รุนแรงอยู่ใกล้ศูนย์ hyperbaric → hyperbaric oxygen ทำให้ half-life สั้นกว่าการให้ O2 100% ที่ความดันบรรยากาศ'])

